using StackExchange.Redis;
using System.Diagnostics;

var mux = ConnectionMultiplexer.Connect("localhost:6379");
var db = mux.GetDatabase();

int iterations = 100_000;
var latencies = new List<double>();

for (int i = 0; i < iterations; i++)
{
    var sw = Stopwatch.StartNew();
    string key = "bench:" + i;
    string value = "val:" + i;
    await db.StringGetSetAsync(key, value);
    sw.Stop();
    latencies.Add(sw.Elapsed.TotalMilliseconds);
}

latencies.Sort();
double p50 = latencies[(int)(iterations * 0.5)];
double p99 = latencies[(int)(iterations * 0.99)];
double p999 = latencies[(int)(iterations * 0.999)];

Console.WriteLine("P50: " + p50.ToString("F3") + " ms");
Console.WriteLine("P99: " + p99.ToString("F3") + " ms");
Console.WriteLine("P99.9: " + p999.ToString("F3") + " ms");
